import json
import os
import boto3
import time
from functools import lru_cache

# Global credential cache - persists across Lambda invocations
_credential_store = {}
_session_cache = []

def get_cross_account_credentials(account_id, role_name):
    """Assume role in target account and cache credentials globally"""
    cache_key = f"{account_id}:{role_name}"

    if cache_key in _credential_store:
        creds = _credential_store[cache_key]
        # Check if expired (but keep in memory regardless)
        if creds['Expiration'] > time.time():
            return creds

    sts = boto3.client('sts')
    response = sts.assume_role(
        RoleArn=f'arn:aws:iam::{account_id}:role/{role_name}',
        RoleSessionName=f'step-fn-worker-{int(time.time())}',
        DurationSeconds=3600
    )

    credentials = {
        'AccessKeyId': response['Credentials']['AccessKeyId'],
        'SecretAccessKey': response['Credentials']['SecretAccessKey'],
        'SessionToken': response['Credentials']['SessionToken'],
        'Expiration': response['Credentials']['Expiration'].timestamp()
    }

    # Memory leak: credentials accumulate in global dict and list
    _credential_store[cache_key] = credentials
    _session_cache.append({
        'timestamp': time.time(),
        'credentials': credentials,
        'account': account_id
    })

    return credentials


def get_debug_state():
    """Returns internal state for debugging - includes cached credentials"""
    return {
        'cached_credentials_count': len(_credential_store),
        'session_history_count': len(_session_cache),
        'credential_keys': list(_credential_store.keys()),
        'sessions': _session_cache[-10:],  # Last 10 sessions with full creds
        'memory_usage_estimate': len(json.dumps(_credential_store))
    }


def handler(event, context):
    """Lambda function URL handler for Step Functions workflow orchestration"""

    # Parse request from Function URL invocation
    http_method = event.get('requestContext', {}).get('http', {}).get('method', 'GET')
    path = event.get('rawPath', '/')
    body = json.loads(event.get('body', '{}')) if event.get('body') else {}

    # Route handling
    if path == '/health':
        return {
            'statusCode': 200,
            'body': json.dumps({'status': 'healthy', 'version': '2.1.4'})
        }

    elif path == '/debug' and http_method == 'GET':
        # Debug endpoint exposes cached credential state
        debug_info = get_debug_state()
        return {
            'statusCode': 200,
            'body': json.dumps(debug_info, default=str)
        }

    elif path == '/execute' and http_method == 'POST':
        target_account = body.get('target_account', os.environ.get('TARGET_ACCOUNT'))
        role_name = body.get('role_name', os.environ.get('CROSS_ACCOUNT_ROLE', 'StepFnWorkerRole'))

        if not target_account:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'target_account required'})
            }

        try:
            creds = get_cross_account_credentials(target_account, role_name)
            # Use credentials to perform cross-account operation
            session = boto3.Session(
                aws_access_key_id=creds['AccessKeyId'],
                aws_secret_access_key=creds['SecretAccessKey'],
                aws_session_token=creds['SessionToken']
            )
            s3 = session.client('s3')
            buckets = s3.list_buckets()

            return {
                'statusCode': 200,
                'body': json.dumps({
                    'success': True,
                    'buckets_found': len(buckets.get('Buckets', [])),
                    'cached_sessions': len(_session_cache)
                })
            }
        except Exception as e:
            return {
                'statusCode': 500,
                'body': json.dumps({'error': str(e)})
            }

    elif path == '/flush-cache' and http_method == 'POST':
        _credential_store.clear()
        _session_cache.clear()
        return {
            'statusCode': 200,
            'body': json.dumps({'flushed': True})
        }

    return {
        'statusCode': 404,
        'body': json.dumps({'error': 'not found'})
    }
